import{_ as e,o as a,c as n,a3 as d}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"大语言模型原理","description":"从概率语言建模、Token、向量表示和 Transformer 出发，理解训练、推理、采样、能力边界与幻觉。","frontmatter":{"title":"大语言模型原理","description":"从概率语言建模、Token、向量表示和 Transformer 出发，理解训练、推理、采样、能力边界与幻觉。","verified_at":"2026-07-28"},"headers":[],"relativePath":"py-agent/foundations/model-principles/index.md","filePath":"py-agent/foundations/model-principles/index.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-principles/index.md"};function o(r,t,l,p,s,c){return a(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="大语言模型原理" tabindex="-1">大语言模型原理 <a class="header-anchor" href="#大语言模型原理" aria-label="Permalink to &quot;大语言模型原理&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>模型应用不能只停留在“把文本发给 API，再读取一段文本”。当输出不稳定、上下文超限、事实错误或延迟过高时，应用开发者必须知道问题发生在文本表示、模型计算、生成策略还是应用验证层。本分组建立一套足够支撑 Agent 开发的模型心智模型，但不把读者带入完整的机器学习数学与训练工程课程。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成本分组后，你应当能够：</p><ol><li>用条件概率和自回归过程解释模型怎样生成文本。</li><li>区分字符、单词、Token、Token ID、向量和上下文化表示。</li><li>沿 Transformer 的数据流解释 Attention、前馈层、残差与层叠结构。</li><li>区分预训练、监督微调、偏好优化与请求时提示。</li><li>解释 temperature、top-p、停止条件和 KV cache 分别影响什么。</li><li>从生成机制推导模型的能力边界，并为事实、结构和业务结果安排应用侧验证。</li></ol><h2 id="_2-内容组织" tabindex="-1">2. 内容组织 <a class="header-anchor" href="#_2-内容组织" aria-label="Permalink to &quot;2. 内容组织&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>核心问题</th></tr></thead><tbody><tr><td>1</td><td><a href="/py-agent/foundations/model-principles/llm-probabilistic-generation">语言模型与概率生成</a></td><td>模型究竟计算什么，为什么是生成而不是查询？</td></tr><tr><td>2</td><td><a href="/py-agent/foundations/model-principles/tokens-context-window">Token 与上下文窗口</a></td><td>文本怎样进入模型，一次请求能容纳多少信息？</td></tr><tr><td>3</td><td><a href="/py-agent/foundations/model-principles/vector-representations-embeddings">向量表示与 Embedding</a></td><td>离散符号怎样变成可学习、可比较的数值表示？</td></tr><tr><td>4</td><td><a href="/py-agent/foundations/model-principles/transformer-attention">Transformer 与 Attention</a></td><td>每个位置怎样结合上下文形成新的表示？</td></tr><tr><td>5</td><td><a href="/py-agent/foundations/model-principles/pretraining-posttraining">预训练与后训练</a></td><td>参数中的能力和行为偏好怎样形成？</td></tr><tr><td>6</td><td><a href="/py-agent/foundations/model-principles/inference-sampling">推理与采样</a></td><td>训练完成的模型怎样逐 Token 产生一次输出？</td></tr><tr><td>7</td><td><a href="/py-agent/foundations/model-principles/model-capabilities-hallucination">模型能力与幻觉</a></td><td>模型为什么既有通用能力，又会流畅地犯错？</td></tr></tbody></table><p>前四篇描述模型接收文本并计算表示的机制，第五篇说明参数如何形成，第六篇说明参数如何在请求时运行，第七篇把这些机制转化为应用边界。这个顺序不是模型 API 的操作步骤，而是一条从输入表示到输出风险的因果链。</p><h2 id="_3-学习边界" tabindex="-1">3. 学习边界 <a class="header-anchor" href="#_3-学习边界" aria-label="Permalink to &quot;3. 学习边界&quot;">​</a></h2><p>本分组会使用少量概率、向量和矩阵直觉，但不要求微积分或线性代数先修知识。它不展开训练集群、反向传播推导、分布式推理、量化、模型部署和具体供应商参数表。</p><p>模型请求、消息层级、结构化输出、重试和评测属于下一分组“模型应用基础”。Embedding 检索、向量数据库和 RAG 会在后续专门模块中讲解。</p>',12)])])}const m=e(i,[["render",o]]);export{f as __pageData,m as default};
